await page.goto('/login');
const roles = ['banner', 'navigation', 'toolbar', 'status'];
let bar = null;
for (const role of roles) {
  const loc = page.getByRole(role).first();
  if ((await loc.count()) > 0) { bar = loc; break; }
}
if (!bar) throw new Error('no landing bar found on /login');
await expect(bar).toBeVisible();
await expect(bar).toHaveCSS('z-index', '2');
